lead_name = #{leadName}, contact_name = #{contactName}, mobile = #{mobile}, wechat = #{wechat}, company_name = #{companyName}, source_code = #{sourceCode}, status = #{status}, priority = #{priority}, legal_demand = #{legalDemand}, estimated_amount = #{estimatedAmount}, next_follow_time = #{nextFollowTime}, invalid_reason = #{invalidReason}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
