mapper.update:
update biz_lead set owner_id = #{ownerId}, dept_id = (select dept_id from sys_user where user_id = #{ownerId}), pool_status = '0',
status = case when status = '0' then '1' else status end, pool_reason = null,
update_by = #{updateBy}, update_time = sysdate() where lead_id = #{leadId} and del_flag = '0' and status = #{expectedStatus}

update biz_lead set customer_id = #{customerId}, status = '3', converted_time = sysdate(),
update_by = #{updateBy}, update_time = sysdate()
where lead_id = #{leadId} and del_flag = '0' and customer_id is null and status = #{expectedStatus}

mapper.select:
select f.followup_id as followupId, f.lead_id as leadId, l.lead_name as leadName, f.follow_type as followType, f.follow_result as followResult, f.content, f.next_follow_time as nextFollowTime, f.follow_user_id as followUserId, u.nick_name as followUserName, f.task_status as taskStatus, f.create_time as createTime from biz_lead_followup f inner join biz_lead l on l.lead_id = f.lead_id left join sys_user u on u.user_id = f.follow_user_id
and f.lead_id = #{leadId} and f.follow_user_id = #{currentUserId} and f.task_status = #{taskStatus}
order by f.create_time desc

mapper.update:
update biz_lead_followup set follow_type=#{followType}, follow_result=#{followResult}, content=#{content},
next_follow_time=#{nextFollowTime}, task_status=#{taskStatus}, update_by=#{updateBy}, update_time=sysdate()
where followup_id=#{followupId} and lead_id=#{leadId}

update biz_lead_setting set setting_type=#{settingType}, setting_code=#{settingCode}, setting_name=#{settingName},
color=#{color}, order_num=#{orderNum}, status=#{status}, remark=#{remark}, update_by=#{updateBy}, update_time=sysdate()
where setting_id=#{settingId}
